class Solution {
public:
    bool isArmstrong(int n) {
        string s = to_string(n);
        int k = s.size();
        long long sum = 0;
        for (char c : s) {
            long long p = 1;
            int d = c - '0';
            for (int i = 0; i < k; ++i) p *= d;
            sum += p;
        }
        return sum == n;
    }
};

class Solution {
    public boolean isArmstrong(int n) {
        String s = String.valueOf(n);
        int k = s.length();
        long sum = 0;
        for (char c : s.toCharArray()) {
            long p = 1;
            int d = c - '0';
            for (int i = 0; i < k; i++) p *= d;
            sum += p;
        }
        return sum == n;
    }
}

var isArmstrong = function(n) {
    const s = String(n);
    const k = s.length;
    let sum = 0;
    for (const c of s) {
        sum += Math.pow(Number(c), k);
    }
    return sum === n;
};
